// Applies a percentage discount to a cart total.
export function applyDiscount(total, percent) {
  return total * (1 - percent / 100);
}

// Volume discount: orders over $100 get 10% off.
export function applyVolumeDiscount(total) {
  return total > 100 ? applyDiscount(total, 10) : total;
}
